import{f as u}from"./LabKit-BiYSPoJv.js";const e=(n,d,o,x)=>({eu:n,es:d,en:x,ar:o.replace(/\{,\}/g,".")}),a=n=>({eu:n,es:n,en:n,ar:n.replace(/\{,\}/g,".")}),$=n=>u(n),s=(n,...d)=>({eu:[n.eu,...d.map(o=>o.eu)].join(" "),es:[n.es,...d.map(o=>o.es)].join(" "),en:[n.en,...d.map(o=>o.en)].join(" "),ar:[n.ar,...d.map(o=>o.ar)].join(" ")}),i=n=>e(`Ebatzi ${n}.`,`Resuelve ${n}.`,`حُلّ ${n}.`,`Solve ${n}.`),c=n=>e(`Ebatzi Gaussen metodoaz ${n}.`,`Resuelve por Gauss ${n}.`,`حُلّ بطريقة غاوس ${n}.`,`Solve by Gaussian elimination ${n}.`),t=n=>e(`Eman ${n} balioa.`,`Da el valor de ${n}.`,`اكتب قيمة ${n}.`,`Give the value of ${n}.`),r=e("Eman $x$ ezezagunaren baliorik handiena.","Da el mayor valor de $x$.","اكتب أكبر قيمة لـ $x$.","Give the largest value of $x$."),y=e("Zenbat soluzio ditu?","¿Cuántas soluciones tiene?","كم حلًّا له؟","How many solutions does it have?"),l=n=>e(`Zenbat puntu oso daude ${n} eskualdean?`,`¿Cuántos puntos de coordenadas enteras hay en la región ${n}?`,`كم نقطة إحداثياتها صحيحة في المنطقة ${n}؟`,`How many points with integer coordinates are there in the region ${n}?`),g=[{id:113001,prompt:e("Zenbat soluzio ditu $x+y=5$ ekuazioak?","¿Cuántas soluciones tiene la ecuación $x+y=5$?","كم حلًّا للمعادلة $x+y=5$؟","How many solutions does the equation $x+y=5$ have?"),options:[e("Infinitu","Infinitas","ما لا نهاية","Infinitely many"),e("Bat","Una","حل واحد","One"),e("Bat ere ez","Ninguna","لا حل","None")],correctIndex:0,explanation:e("$x$ balio bakoitzak $y$ bat ematen du: $(0,5)$, $(1,4)$, $(2,3)$…","Cada valor de $x$ da un $y$: $(0,5)$, $(1,4)$, $(2,3)$…","كل قيمة لـ $x$ تعطي $y$: $(0,5)$ و$(1,4)$ و$(2,3)$…","Each value of $x$ gives a $y$: $(0,5)$, $(1,4)$, $(2,3)$…"),topic:"linear-equations"},{id:113002,prompt:e("Sistema bateko bi ekuazioak bi zuzen paralelo desberdin dira. Zenbat soluzio ditu?","Las dos ecuaciones de un sistema son dos rectas paralelas distintas. ¿Cuántas soluciones tiene?","معادلتا نظام مستقيمان متوازيان مختلفان. كم حلًّا له؟","The two equations of a system are two different parallel lines. How many solutions does it have?"),options:[e("Bat","Una","حل واحد","One"),e("Bat ere ez","Ninguna","لا حل","None"),e("Infinitu","Infinitas","ما لا نهاية","Infinitely many")],correctIndex:1,explanation:e("Zuzen paraleloek ez dute punturik komunean: sistema bateraezina da.","Dos rectas paralelas no tienen ningún punto en común: el sistema es incompatible.","ليس لمستقيمين متوازيين أي نقطة مشتركة: النظام غير متوافق.","Two parallel lines have no point in common: the system is inconsistent."),topic:"classify-systems"},{id:113003,prompt:e("$\\begin{cases}x+y=7\\\\ x-y=1\\end{cases}$ sisteman, zer ateratzen da bi ekuazioak batzean?","En $\\begin{cases}x+y=7\\\\ x-y=1\\end{cases}$, ¿qué sale al sumar las dos ecuaciones?","في $\\begin{cases}x+y=7\\\\ x-y=1\\end{cases}$، ماذا نحصل عند جمع المعادلتين؟","In $\\begin{cases}x+y=7\\\\ x-y=1\\end{cases}$, what do you get when you add the two equations?"),options:[a("$2x=8$"),a("$2y=6$"),a("$2x=6$")],correctIndex:0,explanation:e("$(x+y)+(x-y)=7+1$; beraz, $2x=8$ eta $x=4$.","$(x+y)+(x-y)=7+1$, así que $2x=8$ y $x=4$.","$(x+y)+(x-y)=7+1$، إذن $2x=8$ و$x=4$.","$(x+y)+(x-y)=7+1$, so $2x=8$ and $x=4$."),topic:"equivalent-systems"},{id:113004,prompt:e("${z}=2$ eta $y+z=5$ badira, zenbat balio du $y$ ezezagunak?","Si ${z}=2$ e $y+z=5$, ¿cuánto vale $y$?","إذا كان ${z}=2$ و$y+z=5$ فكم قيمة $y$؟","If ${z}=2$ and $y+z=5$, what is $y$?"),options:[a("$7$"),a("$3$"),a("$2$")],correctIndex:1,explanation:a("$y=5-2=3$"),topic:"triangular-systems"},{id:113005,prompt:e("Zenbatez biderkatu behar da $x-y=1$, $3x+2y=4$ ekuazioari kentzean $x$ desager dadin?","¿Por cuánto hay que multiplicar $x-y=1$ para que, al restarla de $3x+2y=4$, desaparezca la $x$?","في أي عدد نضرب $x-y=1$ لكي يختفي $x$ عند طرحها من $3x+2y=4$؟","By how much must you multiply $x-y=1$ so that, when you subtract it from $3x+2y=4$, the $x$ disappears?"),options:[a("$2$"),a("$-1$"),a("$3$")],correctIndex:2,explanation:e("$3x-3\\cdot x=0$: kendu $3(x-y)=3$.","$3x-3\\cdot x=0$: resta $3(x-y)=3$.","$3x-3\\cdot x=0$: اطرح $3(x-y)=3$.","$3x-3\\cdot x=0$: subtract $3(x-y)=3$."),topic:"gauss-method"},{id:113006,prompt:e("$y=x$ eta $x^2+y^2=8$ badira, zein balio har ditzake $x$ ezezagunak?","Si $y=x$ y $x^2+y^2=8$, ¿qué valores puede tomar $x$?","إذا كان $y=x$ و$x^2+y^2=8$ فما القيم الممكنة لـ $x$؟","If $y=x$ and $x^2+y^2=8$, what values can $x$ take?"),options:[a("$x=4$"),a("$x=2$"),a("$x=\\pm 2$")],correctIndex:2,explanation:e("$2x^2=8$; beraz, $x^2=4$ eta $x=\\pm 2$.","$2x^2=8$, así que $x^2=4$ y $x=\\pm 2$.","$2x^2=8$، إذن $x^2=4$ و$x=\\pm 2$.","$2x^2=8$, so $x^2=4$ and $x=\\pm 2$."),topic:"nonlinear-substitution"},{id:113007,prompt:e("Logaritmo hauetako zein ez dago?","¿Cuál de estos logaritmos no existe?","أي هذه اللوغاريتمات غير موجود؟","Which of these logarithms does not exist?"),options:[a("$\\log 1$"),a("$\\log(-2)$"),a("$\\log 0{,}5$")],correctIndex:1,explanation:e("Zenbaki positiboen logaritmoak bakarrik daude.","Solo existen los logaritmos de números positivos.","لا توجد إلا لوغاريتمات الأعداد الموجبة.","Only the logarithms of positive numbers exist."),topic:"radical-log-systems"},{id:113008,prompt:e("$(0,0)$ puntuak betetzen al du $2x+y\\ge 3$ inekuazioa?","¿Cumple el punto $(0,0)$ la inecuación $2x+y\\ge 3$?","هل تحقق النقطة $(0,0)$ المتراجحة $2x+y\\ge 3$؟","Does the point $(0,0)$ satisfy the inequality $2x+y\\ge 3$?"),options:[e("Bai","Sí","نعم","Yes"),e("Zuzenean dago","Está en la recta","إنها على المستقيم","It is on the line"),e("Ez","No","لا","No")],correctIndex:2,explanation:e("$2\\cdot 0+0=0$, eta 0 ez da 3 baino handiagoa edo berdina.","$2\\cdot 0+0=0$, y 0 no es mayor ni igual que 3.","$2\\cdot 0+0=0$، و0 ليس أكبر من 3 ولا يساويه.","$2\\cdot 0+0=0$, and 0 is not greater than or equal to 3."),topic:"half-plane-regions"}],m=[{id:1,stage:"linear",prompt:e("$(1,2,k)$ hirukotea $x+y+z=6$ ekuazioaren soluzioa da. Zenbat balio du $k$?","La terna $(1,2,k)$ es solución de $x+y+z=6$. ¿Cuánto vale $k$?","الثلاثية $(1,2,k)$ حل للمعادلة $x+y+z=6$. كم قيمة $k$؟","The triple $(1,2,k)$ is a solution of $x+y+z=6$. What is $k$?"),expected:$(3),hint:e("Ordeztu $x=1$ eta $y=2$.","Sustituye $x=1$ e $y=2$.","عوّض $x=1$ و$y=2$.","Substitute $x=1$ and $y=2$."),explanation:a("$1+2+k=6\\ \\to\\ k=3$")},{id:2,stage:"linear",prompt:e("Aurkitu $m$, $\\begin{cases}2x+y=1\\\\ mx+3y=5\\end{cases}$ bateraezina izan dadin.","Halla $m$ para que $\\begin{cases}2x+y=1\\\\ mx+3y=5\\end{cases}$ sea incompatible.","أوجد $m$ ليكون $\\begin{cases}2x+y=1\\\\ mx+3y=5\\end{cases}$ غير متوافق.","Find $m$ so that $\\begin{cases}2x+y=1\\\\ mx+3y=5\\end{cases}$ is inconsistent."),expected:$(6),hint:e("Zuzenek paraleloak izan behar dute: $\\frac{2}{m}=\\frac{1}{3}$.","Las rectas tienen que ser paralelas: $\\frac{2}{m}=\\frac{1}{3}$.","يجب أن يتوازى المستقيمان: $\\frac{2}{m}=\\frac{1}{3}$.","The lines must be parallel: $\\frac{2}{m}=\\frac{1}{3}$."),explanation:e("$m=6$, eta $\\frac{1}{5}\\neq\\frac{1}{3}$: paraleloak dira, ez berdinak.","$m=6$, y $\\frac{1}{5}\\neq\\frac{1}{3}$: paralelas, no coincidentes.","$m=6$، و$\\frac{1}{5}\\neq\\frac{1}{3}$: متوازيان لا منطبقان.","$m=6$, and $\\frac{1}{5}\\neq\\frac{1}{3}$: parallel, not the same line.")},{id:3,stage:"linear",prompt:e("$\\begin{cases}x+2y=8\\\\ 3x+y=9\\end{cases}$ sisteman, egin $E_2-3E_1$. Zein zenbakik biderkatzen du $y$ ekuazio berrian?","En $\\begin{cases}x+2y=8\\\\ 3x+y=9\\end{cases}$, haz $E_2-3E_1$. ¿Qué número multiplica a $y$ en la ecuación nueva?","في $\\begin{cases}x+2y=8\\\\ 3x+y=9\\end{cases}$ أجرِ $E_2-3E_1$. ما العدد الذي يضرب $y$ في المعادلة الجديدة؟","In $\\begin{cases}x+2y=8\\\\ 3x+y=9\\end{cases}$, do $E_2-3E_1$. What number multiplies $y$ in the new equation?"),expected:$(-5),hint:e("Kendu $3x+6y=24$.","Resta $3x+6y=24$.","اطرح $3x+6y=24$.","Subtract $3x+6y=24$."),explanation:a("$(3x+y)-3(x+2y)=9-24\\ \\to\\ -5y=-15$")},{id:4,stage:"linear",prompt:s(i("$\\begin{cases}x+2y=8\\\\ 3x+y=9\\end{cases}$"),t("$x$")),expected:$(2),hint:e("$-5y=-15$ ekuaziotik, $y=3$.","De $-5y=-15$, $y=3$.","من $-5y=-15$ نجد $y=3$.","From $-5y=-15$, $y=3$."),explanation:a("$y=3,\\ x=8-6=2$")},{id:5,stage:"gauss",prompt:s(i("$\\begin{cases}x+y-z=1\\\\ 2y+z=7\\\\ 3z=9\\end{cases}$"),t("$x$")),expected:$(2),hint:e("Hasi behean: ${z}=3$.","Empieza abajo: ${z}=3$.","ابدأ من الأسفل: ${z}=3$.","Start at the bottom: ${z}=3$."),explanation:a("${z}=3,\\ y=2,\\ x=1-2+3=2$")},{id:6,stage:"gauss",prompt:s(c("$\\begin{cases}x+y+z=2\\\\ x+2y+3z=5\\\\ x+3y+2z=2\\end{cases}$"),t("${z}$")),expected:$(2),hint:e("Egin $E_2-E_1$ eta $E_3-E_1$.","Haz $E_2-E_1$ y $E_3-E_1$.","أجرِ $E_2-E_1$ و$E_3-E_1$.","Do $E_2-E_1$ and $E_3-E_1$."),explanation:a("$y+2z=3,\\ 2y+z=0\\ \\to\\ -3z=-6,\\ z=2$")},{id:7,stage:"gauss",prompt:e("Mailakatu $\\left(\\begin{array}{cc|c}1&2&4\\\\ 3&5&9\\end{array}\\right)$, $E_2-3E_1$ eginda. Zein zenbaki geratzen da bigarren errenkadaren azken zutabean?","Escalona $\\left(\\begin{array}{cc|c}1&2&4\\\\ 3&5&9\\end{array}\\right)$ con $E_2-3E_1$. ¿Qué número queda en la última columna de la segunda fila?","حوّل $\\left(\\begin{array}{cc|c}1&2&4\\\\ 3&5&9\\end{array}\\right)$ إلى الشكل الدرجي بـ $E_2-3E_1$. ما العدد الذي يبقى في آخر عمود من الصف الثاني؟","Make $\\left(\\begin{array}{cc|c}1&2&4\\\\ 3&5&9\\end{array}\\right)$ triangular with $E_2-3E_1$. What number is left in the last column of the second row?"),expected:$(-3),hint:e("Marraren ondoren ere egiten da eragiketa.","La operación también se hace tras la barra.","تُجرى العملية بعد الخط أيضًا.","The operation is done after the bar too."),explanation:a("$9-3\\cdot 4=-3$")},{id:8,stage:"gauss",prompt:e("Hiru zenbakiren batura 24 da. Bigarrena lehenaren bikoitza da, eta hirugarrena bigarrena baino 4 handiagoa. Zein da hirugarrena?","Tres números suman 24. El segundo es el doble del primero y el tercero es 4 más que el segundo. ¿Cuál es el tercero?","مجموع ثلاثة أعداد 24. الثاني ضعف الأول، والثالث يزيد على الثاني بـ 4. ما الثالث؟","Three numbers add up to 24. The second is twice the first and the third is 4 more than the second. What is the third?"),expected:$(12),hint:e("Idatzi denak lehenaren funtzioan: $x$, $2x$ eta $2x+4$.","Escríbelos todos con el primero: $x$, $2x$ y $2x+4$.","اكتبها كلها بدلالة الأول: $x$ و$2x$ و$2x+4$.","Write them all with the first: $x$, $2x$ and $2x+4$."),explanation:e("$x+2x+(2x+4)=24$, beraz $x=4$; hirugarrena $2\\cdot 4+4=12$ da.","$x+2x+(2x+4)=24$, así que $x=4$; el tercero es $2\\cdot 4+4=12$.","$x+2x+(2x+4)=24$، إذن $x=4$؛ والثالث $2\\cdot 4+4=12$.","$x+2x+(2x+4)=24$, so $x=4$; the third is $2\\cdot 4+4=12$.")},{id:9,stage:"discussion",prompt:e("Sistema mailakatu baten azken errenkada $(0\\ \\ 0\\ \\ 3\\mid 6)$ da. Zenbat balio du ${z}$ ezezagunak?","La última fila de un sistema escalonado es $(0\\ \\ 0\\ \\ 3\\mid 6)$. ¿Cuánto vale ${z}$?","الصف الأخير لنظام درجي هو $(0\\ \\ 0\\ \\ 3\\mid 6)$. كم قيمة ${z}$؟","The last row of a triangular system is $(0\\ \\ 0\\ \\ 3\\mid 6)$. What is ${z}$?"),expected:$(2),hint:e("Errenkadak $3z=6$ esan nahi du.","La fila quiere decir $3z=6$.","الصف يعني $3z=6$.","The row means $3z=6$."),explanation:a("$3z=6\\ \\to\\ z=2$")},{id:10,stage:"discussion",prompt:e("Sistema baten soluzioak $(2-\\lambda,\\ 1+\\lambda,\\ \\lambda)$ dira. Zenbat balio du $x$ ezezagunak ${z}=5$ denean?","Las soluciones de un sistema son $(2-\\lambda,\\ 1+\\lambda,\\ \\lambda)$. ¿Cuánto vale $x$ cuando ${z}=5$?","حلول نظام هي $(2-\\lambda,\\ 1+\\lambda,\\ \\lambda)$. كم قيمة $x$ عندما ${z}=5$؟","The solutions of a system are $(2-\\lambda,\\ 1+\\lambda,\\ \\lambda)$. What is $x$ when ${z}=5$?"),expected:$(-3),hint:e("${z}=\\lambda$ da; beraz, $\\lambda=5$.","Como ${z}=\\lambda$, $\\lambda=5$.","بما أن ${z}=\\lambda$ فإن $\\lambda=5$.","As ${z}=\\lambda$, $\\lambda=5$."),explanation:a("$\\lambda=5\\ \\to\\ x=2-5=-3$")},{id:11,stage:"discussion",prompt:e("Ebatzi $\\begin{cases}x+y+z=5\\\\ y-z=1\\end{cases}$, ${z}=\\lambda$ eginda. Zenbat balio du $x$ ezezagunak $\\lambda=2$ denean?","Resuelve $\\begin{cases}x+y+z=5\\\\ y-z=1\\end{cases}$ con ${z}=\\lambda$. ¿Cuánto vale $x$ para $\\lambda=2$?","حُلّ $\\begin{cases}x+y+z=5\\\\ y-z=1\\end{cases}$ مع ${z}=\\lambda$. كم قيمة $x$ عندما $\\lambda=2$؟","Solve $\\begin{cases}x+y+z=5\\\\ y-z=1\\end{cases}$ with ${z}=\\lambda$. What is $x$ for $\\lambda=2$?"),expected:$(0),hint:e("Bigarrenetik, $y=1+\\lambda$.","De la segunda, $y=1+\\lambda$.","من الثانية: $y=1+\\lambda$.","From the second, $y=1+\\lambda$."),explanation:a("$y=1+\\lambda,\\ x=4-2\\lambda=4-4=0$")},{id:12,stage:"discussion",prompt:e("Aurkitu $\\begin{cases}x+y=2\\\\ 2x+ay=3\\end{cases}$ bateraezina egiten duen $a$ balioa.","Halla el valor de $a$ que hace incompatible $\\begin{cases}x+y=2\\\\ 2x+ay=3\\end{cases}$.","أوجد قيمة $a$ التي تجعل $\\begin{cases}x+y=2\\\\ 2x+ay=3\\end{cases}$ غير متوافق.","Find the value of $a$ that makes $\\begin{cases}x+y=2\\\\ 2x+ay=3\\end{cases}$ inconsistent."),expected:$(2),hint:e("Egin $E_2-2E_1$ eta begiratu $y$ ezezagunaren koefizienteari.","Haz $E_2-2E_1$ y mira el coeficiente de $y$.","أجرِ $E_2-2E_1$ وانظر إلى معامل $y$.","Do $E_2-2E_1$ and look at the coefficient of $y$."),explanation:e("$E_2-2E_1$ eragiketak $(a-2)y=-1$ ematen du; $a=2$ denean, $0y=-1$.","$E_2-2E_1$ da $(a-2)y=-1$; con $a=2$, $0y=-1$.","تعطي $E_2-2E_1$ المعادلة $(a-2)y=-1$؛ ومع $a=2$ يكون $0y=-1$.","$E_2-2E_1$ gives $(a-2)y=-1$; with $a=2$, $0y=-1$.")},{id:13,stage:"nonlinear",prompt:s(i("$\\begin{cases}x+y=6\\\\ xy=8\\end{cases}$"),r),expected:$(4),hint:e("Ordeztu $y=6-x$.","Sustituye $y=6-x$.","عوّض $y=6-x$.","Substitute $y=6-x$."),explanation:a("$x^2-6x+8=0\\ \\to\\ x=2,\\ x=4$")},{id:14,stage:"nonlinear",prompt:s(i("$\\begin{cases}\\log x+\\log y=2\\\\ x=4y\\end{cases}$"),t("$x$")),expected:$(20),hint:e("$\\log x+\\log y=\\log(xy)$, eta $2=\\log 100$.","$\\log x+\\log y=\\log(xy)$ y $2=\\log 100$.","$\\log x+\\log y=\\log(xy)$ و$2=\\log 100$.","$\\log x+\\log y=\\log(xy)$ and $2=\\log 100$."),explanation:e("$4y^2=100$, beraz $y=5$ ($-5$ zenbakiak ez du balio), eta $x=20$.","$4y^2=100$, así que $y=5$ ($-5$ no vale), y $x=20$.","$4y^2=100$، إذن $y=5$ ($-5$ لا يصلح) و$x=20$.","$4y^2=100$, so $y=5$ ($-5$ does not work), and $x=20$.")},{id:15,stage:"nonlinear",prompt:s(i("$\\begin{cases}2^x+2^y=10\\\\ 2^x-2^y=6\\end{cases}$"),t("$x+y$")),expected:$(4),hint:e("Aldaketa: $u=2^x$, $v=2^y$.","Cambio: $u=2^x$, $v=2^y$.","التغيير: $u=2^x$ و$v=2^y$.","Change: $u=2^x$, $v=2^y$."),explanation:a("$u=8,\\ v=2\\ \\to\\ x=3,\\ y=1\\qquad 3+1=4$")},{id:16,stage:"nonlinear",prompt:e("Laukizuzen baten perimetroa 26 cm da, eta azalera 40 cm². Zenbat neurtzen du alde handienak, zentimetrotan?","Un rectángulo tiene 26 cm de perímetro y 40 cm² de área. ¿Cuánto mide el lado mayor, en centímetros?","مستطيل محيطه 26 سم ومساحته 40 سم². كم طول الضلع الأكبر بالسنتيمتر؟","A rectangle has a perimeter of 26 cm and an area of 40 cm². How long is the longer side, in centimetres?"),expected:$(8),hint:a("$x+y=13,\\ xy=40$"),explanation:a("$x^2-13x+40=0\\ \\to\\ x=5,\\ x=8$")},{id:17,stage:"inequalities",prompt:l("$\\begin{cases}x\\ge 0\\\\ y\\ge 0\\\\ x+y\\le 2\\end{cases}$"),expected:$(6),hint:e("Zenbatu zutabeka: $x=0$, $x=1$, $x=2$.","Cuenta por columnas: $x=0$, $x=1$, $x=2$.","عُدّ عمودًا عمودًا: $x=0$ و$x=1$ و$x=2$.","Count column by column: $x=0$, $x=1$, $x=2$."),explanation:e("$x=0$ denean, 3; $x=1$ denean, 2; $x=2$ denean, 1. Guztira, $3+2+1=6$.","Con $x=0$, 3; con $x=1$, 2; con $x=2$, 1. En total, $3+2+1=6$.","مع $x=0$ ثلاث، ومع $x=1$ اثنتان، ومع $x=2$ واحدة. المجموع $3+2+1=6$.","With $x=0$, 3; with $x=1$, 2; with $x=2$, 1. In all, $3+2+1=6$.")},{id:18,stage:"inequalities",prompt:e("Zein da $y$ ezezagunaren baliorik handiena $\\begin{cases}y\\le 2x\\\\ x\\le 3\\\\ y\\ge 0\\end{cases}$ eskualdean?","¿Cuál es el mayor valor de $y$ en la región $\\begin{cases}y\\le 2x\\\\ x\\le 3\\\\ y\\ge 0\\end{cases}$?","ما أكبر قيمة لـ $y$ في المنطقة $\\begin{cases}y\\le 2x\\\\ x\\le 3\\\\ y\\ge 0\\end{cases}$؟","What is the largest value of $y$ in the region $\\begin{cases}y\\le 2x\\\\ x\\le 3\\\\ y\\ge 0\\end{cases}$?"),expected:$(6),hint:e("Bilatu erpinik altuena.","Busca el vértice más alto.","ابحث عن أعلى رأس.","Look for the highest vertex."),explanation:e("Erpinik altuena $(3,6)$ da: $y=2\\cdot 3=6$.","El vértice más alto es $(3,6)$: $y=2\\cdot 3=6$.","أعلى رأس هو $(3,6)$: $y=2\\cdot 3=6$.","The highest vertex is $(3,6)$: $y=2\\cdot 3=6$.")},{id:19,stage:"inequalities",prompt:e("Aurkitu $k$, $(2,k)$ puntua $3x+y\\le 10$ inekuazioaren muga-zuzenean egon dadin.","Halla $k$ para que el punto $(2,k)$ esté en la recta frontera de $3x+y\\le 10$.","أوجد $k$ لتكون النقطة $(2,k)$ على المستقيم الحدّي للمتراجحة $3x+y\\le 10$.","Find $k$ so that the point $(2,k)$ is on the boundary line of $3x+y\\le 10$."),expected:$(4),hint:a("$3x+y=10$"),explanation:a("$3\\cdot 2+k=10\\ \\to\\ k=4$")},{id:20,stage:"inequalities",prompt:e("$\\begin{cases}x+y\\ge 5\\\\ x\\le 1\\\\ y\\le c\\end{cases}$ eskualdea hutsa da $c$ zenbaki jakin bat baino txikiagoa denean. Zein da zenbaki hori?","La región $\\begin{cases}x+y\\ge 5\\\\ x\\le 1\\\\ y\\le c\\end{cases}$ es vacía si $c$ es menor que cierto número. ¿Cuál?","المنطقة $\\begin{cases}x+y\\ge 5\\\\ x\\le 1\\\\ y\\le c\\end{cases}$ خالية إذا كان $c$ أصغر من عدد معيّن. ما هو؟","The region $\\begin{cases}x+y\\ge 5\\\\ x\\le 1\\\\ y\\le c\\end{cases}$ is empty if $c$ is less than a certain number. Which?"),expected:$(4),hint:e("$x+y$ handiena izkinan dago, $(1,c)$ puntuan.","El mayor $x+y$ está en la esquina $(1,c)$.","أكبر $x+y$ في الزاوية $(1,c)$.","The largest $x+y$ is at the corner $(1,c)$."),explanation:e("$1+c\\ge 5$ behar da, hau da, $c\\ge 4$; $c$ zenbakia 4 baino txikiagoa bada, eskualdea hutsa da.","Hace falta $1+c\\ge 5$, es decir, $c\\ge 4$; si $c$ es menor que 4, la región es vacía.","يلزم $1+c\\ge 5$، أي $c\\ge 4$؛ وإذا كان $c$ أصغر من 4 فالمنطقة خالية.","You need $1+c\\ge 5$, that is, $c\\ge 4$; if $c$ is less than 4, the region is empty.")}],z=[{id:101,stage:"linear",points:10,context:"starter",prompt:e("Aurkitu $a$ eta $b$, $(2,1)$ bikotea $\\begin{cases}ax+y=7\\\\ x-by=0\\end{cases}$ sistemaren soluzioa izan dadin. Eman $a+b$.","Halla $a$ y $b$ para que $(2,1)$ sea solución de $\\begin{cases}ax+y=7\\\\ x-by=0\\end{cases}$. Da $a+b$.","أوجد $a$ و$b$ ليكون $(2,1)$ حلًّا للنظام $\\begin{cases}ax+y=7\\\\ x-by=0\\end{cases}$. اكتب $a+b$.","Find $a$ and $b$ so that $(2,1)$ is a solution of $\\begin{cases}ax+y=7\\\\ x-by=0\\end{cases}$. Give $a+b$."),expected:$(5),hint:e("Ordeztu $x=2$ eta $y=1$.","Sustituye $x=2$ e $y=1$.","عوّض $x=2$ و$y=1$.","Substitute $x=2$ and $y=1$."),explanation:a("$2a+1=7\\ \\to\\ a=3\\qquad 2-b=0\\ \\to\\ b=2\\qquad 3+2=5$")},{id:102,stage:"linear",points:20,context:"advanced",prompt:e("Aurkitu $m$, $\\begin{cases}x+my=3\\\\ 2x+4y=6\\end{cases}$ bateragarri indeterminatua izan dadin.","Halla $m$ para que $\\begin{cases}x+my=3\\\\ 2x+4y=6\\end{cases}$ sea compatible indeterminado.","أوجد $m$ ليكون $\\begin{cases}x+my=3\\\\ 2x+4y=6\\end{cases}$ متوافقًا غير محدد.","Find $m$ so that $\\begin{cases}x+my=3\\\\ 2x+4y=6\\end{cases}$ is consistent and dependent."),expected:$(2),hint:e("Bi ekuazioek gauza bera esan behar dute.","Las dos ecuaciones tienen que decir lo mismo.","يجب أن تقول المعادلتان الشيء نفسه.","The two equations must say the same thing."),explanation:e("Bigarrena lehenaren bikoitza izan behar da: $2m=4$, beraz $m=2$.","La segunda tiene que ser el doble de la primera: $2m=4$, así que $m=2$.","يجب أن تكون الثانية ضعف الأولى: $2m=4$، إذن $m=2$.","The second must be twice the first: $2m=4$, so $m=2$.")},{id:103,stage:"linear",points:30,context:"master",prompt:e("$(1,2)$ eta $(3,-2)$ bikoteak $ax+by=8$ ekuazioaren soluzioak dira. Aurkitu $a$.","Los pares $(1,2)$ y $(3,-2)$ son soluciones de $ax+by=8$. Halla $a$.","الزوجان $(1,2)$ و$(3,-2)$ حلّان للمعادلة $ax+by=8$. أوجد $a$.","The pairs $(1,2)$ and $(3,-2)$ are solutions of $ax+by=8$. Find $a$."),expected:$(4),hint:e("Bikote bakoitzak $a$ eta $b$ ezezagunen ekuazio bat ematen du.","Cada par da una ecuación en $a$ y $b$.","كل زوج يعطي معادلة في $a$ و$b$.","Each pair gives an equation in $a$ and $b$."),explanation:a("$\\begin{cases}a+2b=8\\\\ 3a-2b=8\\end{cases}\\ \\to\\ 4a=16,\\ a=4$")},{id:104,stage:"gauss",points:10,context:"starter",prompt:s(i("$\\begin{cases}x+y+z=6\\\\ y+z=5\\\\ z=3\\end{cases}$"),t("$x\\cdot y\\cdot z$")),expected:$(6),hint:e("Behetik gora: ${z}$, $y$, $x$.","De abajo arriba: ${z}$, $y$, $x$.","من الأسفل إلى الأعلى: ${z}$ ثم $y$ ثم $x$.","From the bottom up: ${z}$, $y$, $x$."),explanation:e("${z}=3$, $y=2$, $x=1$; biderkadura $1\\cdot 2\\cdot 3=6$ da.","${z}=3$, $y=2$, $x=1$; el producto es $1\\cdot 2\\cdot 3=6$.","${z}=3$ و$y=2$ و$x=1$؛ والجداء $1\\cdot 2\\cdot 3=6$.","${z}=3$, $y=2$, $x=1$; the product is $1\\cdot 2\\cdot 3=6$.")},{id:105,stage:"gauss",points:20,context:"advanced",prompt:s(c("$\\begin{cases}x+y+z=0\\\\ 2x+3y+z=1\\\\ x-y+2z=1\\end{cases}$"),t("$y$")),expected:$(-2),hint:e("$E_2-2E_1$ eta $E_3-E_1$.","$E_2-2E_1$ y $E_3-E_1$.","$E_2-2E_1$ و$E_3-E_1$.","$E_2-2E_1$ and $E_3-E_1$."),explanation:a("$y-z=1,\\ -2y+z=1\\ \\to\\ -y=2,\\ y=-2$")},{id:106,stage:"gauss",points:30,context:"master",prompt:e("Kutxa batean 5, 10 eta 20 euroko billeteak daude: 18 billete eta 210 € guztira. 10 eurokoak beste bi motakoak adina dira, batera. Zenbat billete daude 20 eurokoak?","En una caja hay billetes de 5 €, 10 € y 20 €: 18 billetes y 210 € en total. Hay tantos de 10 € como de 5 € y 20 € juntos. ¿Cuántos hay de 20 €?","في صندوق أوراق نقدية من 5 € و10 € و20 €: 18 ورقة و210 € في المجموع. وعدد أوراق 10 € يساوي عدد أوراق 5 € و20 € معًا. كم ورقة من فئة 20 €؟","A box holds €5, €10 and €20 notes: 18 notes and €210 in all. There are as many €10 notes as €5 and €20 notes together. How many €20 notes are there?"),expected:$(5),hint:a("$\\begin{cases}x+y+z=18\\\\ 5x+10y+20z=210\\\\ y=x+z\\end{cases}$"),explanation:e("$y=9$, $x+z=9$ eta $5x+20z=120$; beraz, ${z}=5$.","$y=9$, $x+z=9$ y $5x+20z=120$, así que ${z}=5$.","$y=9$ و$x+z=9$ و$5x+20z=120$، إذن ${z}=5$.","$y=9$, $x+z=9$ and $5x+20z=120$, so ${z}=5$.")},{id:107,stage:"discussion",points:10,context:"starter",prompt:e("Sistema baten soluzioak $(1+2\\lambda,\\ \\lambda,\\ 3-\\lambda)$ dira. Aurkitu $y=2$ duen soluzioa, eta eman $x+z$.","Las soluciones de un sistema son $(1+2\\lambda,\\ \\lambda,\\ 3-\\lambda)$. Halla la que tiene $y=2$ y da $x+z$.","حلول نظام هي $(1+2\\lambda,\\ \\lambda,\\ 3-\\lambda)$. أوجد الحل الذي فيه $y=2$ واكتب $x+z$.","The solutions of a system are $(1+2\\lambda,\\ \\lambda,\\ 3-\\lambda)$. Find the one with $y=2$ and give $x+z$."),expected:$(6),hint:e("$y=\\lambda$ da.","$y=\\lambda$.","$y=\\lambda$.","$y=\\lambda$."),explanation:a("$\\lambda=2\\ \\to\\ x=5,\\ z=1\\qquad 5+1=6$")},{id:108,stage:"discussion",points:20,context:"advanced",prompt:e("Aurkitu $a$, $\\begin{cases}x+y+z=1\\\\ y+2z=3\\\\ (a-1)z=a-1\\end{cases}$ bateragarri indeterminatua izan dadin.","Halla $a$ para que $\\begin{cases}x+y+z=1\\\\ y+2z=3\\\\ (a-1)z=a-1\\end{cases}$ sea compatible indeterminado.","أوجد $a$ ليكون $\\begin{cases}x+y+z=1\\\\ y+2z=3\\\\ (a-1)z=a-1\\end{cases}$ متوافقًا غير محدد.","Find $a$ so that $\\begin{cases}x+y+z=1\\\\ y+2z=3\\\\ (a-1)z=a-1\\end{cases}$ is consistent and dependent."),expected:$(1),hint:e("Azken errenkadak $0z=0$ izan behar du.","La última fila tiene que ser $0z=0$.","يجب أن يكون الصف الأخير $0z=0$.","The last row has to be $0z=0$."),explanation:e("$a=1$ denean, azken errenkada $0z=0$ da.","Con $a=1$ la última fila es $0z=0$.","مع $a=1$ يكون الصف الأخير $0z=0$.","With $a=1$ the last row is $0z=0$.")},{id:109,stage:"discussion",points:30,context:"master",prompt:e("Eztabaidatu $\\begin{cases}x+y+z=2\\\\ x+2y+z=3\\\\ x+y+az=b\\end{cases}$. $a=1$ bada, $b$ zenbakiaren zein balioak ematen ditu infinitu soluzio?","Discute $\\begin{cases}x+y+z=2\\\\ x+2y+z=3\\\\ x+y+az=b\\end{cases}$. Si $a=1$, ¿qué valor de $b$ da infinitas soluciones?","ناقش $\\begin{cases}x+y+z=2\\\\ x+2y+z=3\\\\ x+y+az=b\\end{cases}$. إذا كان $a=1$ فأي قيمة لـ $b$ تعطي ما لا نهاية من الحلول؟","Analyse $\\begin{cases}x+y+z=2\\\\ x+2y+z=3\\\\ x+y+az=b\\end{cases}$. If $a=1$, which value of $b$ gives infinitely many solutions?"),expected:$(2),hint:e("Egin $E_3-E_1$.","Haz $E_3-E_1$.","أجرِ $E_3-E_1$.","Do $E_3-E_1$."),explanation:e("$E_3-E_1$ eragiketak $(a-1)z=b-2$ ematen du; $a=1$ denean, $b-2=0$ behar da: $b=2$.","$E_3-E_1$ da $(a-1)z=b-2$; con $a=1$, hace falta $b-2=0$: $b=2$.","تعطي $E_3-E_1$ المعادلة $(a-1)z=b-2$؛ ومع $a=1$ يلزم $b-2=0$: $b=2$.","$E_3-E_1$ gives $(a-1)z=b-2$; with $a=1$, you need $b-2=0$: $b=2$.")},{id:110,stage:"nonlinear",points:10,context:"starter",prompt:s(i("$\\begin{cases}x-y=2\\\\ x^2+y^2=10\\end{cases}$"),r),expected:$(3),hint:e("Ordeztu $x=y+2$.","Sustituye $x=y+2$.","عوّض $x=y+2$.","Substitute $x=y+2$."),explanation:e("$y^2+2y-3=0$ ekuazioak $y=1$ eta $y=-3$ ematen ditu; beraz, $x=3$ edo $x=-1$.","$y^2+2y-3=0$ da $y=1$ e $y=-3$; así, $x=3$ o $x=-1$.","تعطي $y^2+2y-3=0$ القيمتين $y=1$ و$y=-3$؛ إذن $x=3$ أو $x=-1$.","$y^2+2y-3=0$ gives $y=1$ and $y=-3$; so $x=3$ or $x=-1$.")},{id:111,stage:"nonlinear",points:20,context:"advanced",prompt:s(i("$\\begin{cases}3^x\\cdot 3^y=27\\\\ 3^x\\div 3^y=3\\end{cases}$"),t("$x$")),expected:$(2),hint:e("Berdindu berretzaileak: $3^{x+y}=3^3$.","Iguala los exponentes: $3^{x+y}=3^3$.","ساوِ الأسس: $3^{x+y}=3^3$.","Equate the exponents: $3^{x+y}=3^3$."),explanation:a("$x+y=3,\\ x-y=1\\ \\to\\ x=2$")},{id:112,stage:"nonlinear",points:30,context:"master",prompt:s(i("$\\begin{cases}\\sqrt{x}+\\sqrt{y}=5\\\\ x-y=5\\end{cases}$"),t("$x$")),expected:$(9),hint:a("$x-y=(\\sqrt{x}-\\sqrt{y})(\\sqrt{x}+\\sqrt{y})$"),explanation:e("$\\sqrt{x}-\\sqrt{y}=1$ eta $\\sqrt{x}+\\sqrt{y}=5$: $\\sqrt{x}=3$, $x=9$.","$\\sqrt{x}-\\sqrt{y}=1$ y $\\sqrt{x}+\\sqrt{y}=5$: $\\sqrt{x}=3$, $x=9$.","$\\sqrt{x}-\\sqrt{y}=1$ و$\\sqrt{x}+\\sqrt{y}=5$: $\\sqrt{x}=3$ و$x=9$.","$\\sqrt{x}-\\sqrt{y}=1$ and $\\sqrt{x}+\\sqrt{y}=5$: $\\sqrt{x}=3$, $x=9$.")},{id:113,stage:"inequalities",points:10,context:"starter",prompt:l("$\\begin{cases}x\\ge 0\\\\ y\\ge 0\\\\ x+y\\le 3\\end{cases}$"),expected:$(10),hint:e("Zenbatu zutabeka.","Cuenta por columnas.","عُدّ عمودًا عمودًا.","Count column by column."),explanation:a("$4+3+2+1=10$")},{id:114,stage:"inequalities",points:20,context:"advanced",prompt:e("Lan-talde batek 5 eta 7 pertsona artean izango ditu, eta gutxienez 2 A taldekoak eta 2 B taldekoak. Zenbat konposizio daude, $(A,B)$ bikote gisa?","Un equipo de trabajo tendrá entre 5 y 7 personas, con al menos 2 del grupo A y 2 del grupo B. ¿Cuántas composiciones $(A,B)$ hay?","سيضم فريق عمل بين 5 و7 أشخاص، فيهم 2 على الأقل من المجموعة A و2 من المجموعة B. كم تركيبة $(A,B)$ ممكنة؟","A working team will have between 5 and 7 people, with at least 2 from group A and 2 from group B. How many line-ups $(A,B)$ are there?"),expected:$(9),hint:a("$\\begin{cases}x\\ge 2\\\\ y\\ge 2\\\\ 5\\le x+y\\le 7\\end{cases}$"),explanation:e("Guztira 5 pertsona badira, 2 aukera; 6 badira, 3; 7 badira, 4. Guztira, $2+3+4=9$.","Con 5 personas hay 2; con 6, 3; con 7, 4. En total, $2+3+4=9$.","مع 5 أشخاص تركيبتان، ومع 6 ثلاث، ومع 7 أربع. المجموع $2+3+4=9$.","With 5 people there are 2; with 6, 3; with 7, 4. In all, $2+3+4=9$.")},{id:115,stage:"inequalities",points:30,context:"master",prompt:e("Aurkitu $\\begin{cases}x\\ge 0\\\\ y\\ge 0\\\\ 2x+y\\le 6\\end{cases}$ eskualdearen azalera.","Halla el área de la región $\\begin{cases}x\\ge 0\\\\ y\\ge 0\\\\ 2x+y\\le 6\\end{cases}$.","أوجد مساحة المنطقة $\\begin{cases}x\\ge 0\\\\ y\\ge 0\\\\ 2x+y\\le 6\\end{cases}$.","Find the area of the region $\\begin{cases}x\\ge 0\\\\ y\\ge 0\\\\ 2x+y\\le 6\\end{cases}$."),expected:$(9),hint:e("Triangelu bat da: bilatu erpinak.","Es un triángulo: busca sus vértices.","إنها مثلث: ابحث عن رؤوسه.","It is a triangle: find its vertices."),explanation:e("Erpinak $(0,0)$, $(3,0)$ eta $(0,6)$: azalera $\\frac{3\\cdot 6}{2}=9$.","Vértices $(0,0)$, $(3,0)$ y $(0,6)$: área $\\frac{3\\cdot 6}{2}=9$.","الرؤوس $(0,0)$ و$(3,0)$ و$(0,6)$: المساحة $\\frac{3\\cdot 6}{2}=9$.","Vertices $(0,0)$, $(3,0)$ and $(0,6)$: area $\\frac{3\\cdot 6}{2}=9$.")}],p=[{id:"linear",title:e("Sistema linealak","Sistemas lineales","الأنظمة الخطية","Linear systems"),items:[{id:1,difficulty:"easy",question:e("$(1,1,1)$ hirukotea $\\begin{cases}x+y+z=3\\\\ x-y+z=1\\end{cases}$ sistemaren soluzioa al da?","¿Es $(1,1,1)$ solución de $\\begin{cases}x+y+z=3\\\\ x-y+z=1\\end{cases}$?","هل $(1,1,1)$ حل للنظام $\\begin{cases}x+y+z=3\\\\ x-y+z=1\\end{cases}$؟","Is $(1,1,1)$ a solution of $\\begin{cases}x+y+z=3\\\\ x-y+z=1\\end{cases}$?"),solution:e("Bai: $1+1+1=3$ eta $1-1+1=1$.","Sí: $1+1+1=3$ y $1-1+1=1$.","نعم: $1+1+1=3$ و$1-1+1=1$.","Yes: $1+1+1=3$ and $1-1+1=1$.")},{id:2,difficulty:"easy",question:e("$2x+y-z=4$ ekuazioan, $x=1$ eta $y=2$ badira, zenbat balio du ${z}$ ezezagunak?","En $2x+y-z=4$, si $x=1$ e $y=2$, ¿cuánto vale ${z}$?","في $2x+y-z=4$، إذا كان $x=1$ و$y=2$ فكم قيمة ${z}$؟","In $2x+y-z=4$, if $x=1$ and $y=2$, what is ${z}$?"),solution:a("$2+2-z=4\\ \\to\\ z=0$"),answer:{expected:$(0)}},{id:3,difficulty:"easy",question:e("Sailkatu $\\begin{cases}x+y=3\\\\ x-y=1\\end{cases}$.","Clasifica $\\begin{cases}x+y=3\\\\ x-y=1\\end{cases}$.","صنّف $\\begin{cases}x+y=3\\\\ x-y=1\\end{cases}$.","Classify $\\begin{cases}x+y=3\\\\ x-y=1\\end{cases}$."),solution:e("Bateragarri determinatua: $\\frac{1}{1}\\neq\\frac{1}{-1}$; soluzioa $(2,1)$ da.","Compatible determinado: $\\frac{1}{1}\\neq\\frac{1}{-1}$; la solución es $(2,1)$.","متوافق محدد: $\\frac{1}{1}\\neq\\frac{1}{-1}$؛ والحل $(2,1)$.","Consistent and independent: $\\frac{1}{1}\\neq\\frac{1}{-1}$; the solution is $(2,1)$.")},{id:4,difficulty:"easy",question:e("Sailkatu $\\begin{cases}3x-y=2\\\\ 6x-2y=4\\end{cases}$.","Clasifica $\\begin{cases}3x-y=2\\\\ 6x-2y=4\\end{cases}$.","صنّف $\\begin{cases}3x-y=2\\\\ 6x-2y=4\\end{cases}$.","Classify $\\begin{cases}3x-y=2\\\\ 6x-2y=4\\end{cases}$."),solution:e("Bigarrena lehenaren bikoitza da: bateragarri indeterminatua.","La segunda es el doble de la primera: compatible indeterminado.","الثانية ضعف الأولى: متوافق غير محدد.","The second is twice the first: consistent and dependent.")},{id:5,difficulty:"medium",question:e("Aurkitu $k$, $\\begin{cases}x+ky=2\\\\ 3x+6y=5\\end{cases}$ bateraezina izan dadin.","Halla $k$ para que $\\begin{cases}x+ky=2\\\\ 3x+6y=5\\end{cases}$ sea incompatible.","أوجد $k$ ليكون $\\begin{cases}x+ky=2\\\\ 3x+6y=5\\end{cases}$ غير متوافق.","Find $k$ so that $\\begin{cases}x+ky=2\\\\ 3x+6y=5\\end{cases}$ is inconsistent."),solution:e("$\\frac{1}{3}=\\frac{k}{6}$ denean, $k=2$; eta $\\frac{2}{5}\\neq\\frac{1}{3}$.","$\\frac{1}{3}=\\frac{k}{6}$ da $k=2$, y $\\frac{2}{5}\\neq\\frac{1}{3}$.","$\\frac{1}{3}=\\frac{k}{6}$ يعطي $k=2$، و$\\frac{2}{5}\\neq\\frac{1}{3}$.","$\\frac{1}{3}=\\frac{k}{6}$ gives $k=2$, and $\\frac{2}{5}\\neq\\frac{1}{3}$."),answer:{expected:$(2)}},{id:6,difficulty:"medium",question:e("Bihurtu $\\begin{cases}x+y=6\\\\ 3x-2y=8\\end{cases}$, $E_2-3E_1$ eginda, eta ebatzi. Eman $y$.","Transforma $\\begin{cases}x+y=6\\\\ 3x-2y=8\\end{cases}$ con $E_2-3E_1$ y resuelve. Da $y$.","حوّل $\\begin{cases}x+y=6\\\\ 3x-2y=8\\end{cases}$ بـ $E_2-3E_1$ وحُلّه. اكتب $y$.","Transform $\\begin{cases}x+y=6\\\\ 3x-2y=8\\end{cases}$ with $E_2-3E_1$ and solve. Give $y$."),solution:a("$-5y=8-18=-10\\ \\to\\ y=2,\\ x=4$"),answer:{expected:$(2)}},{id:7,difficulty:"medium",question:e("$\\begin{cases}x+y=5\\\\ 2x-y=1\\end{cases}$ eta $\\begin{cases}x+y=5\\\\ 3x=6\\end{cases}$ baliokideak al dira?","¿Son equivalentes $\\begin{cases}x+y=5\\\\ 2x-y=1\\end{cases}$ y $\\begin{cases}x+y=5\\\\ 3x=6\\end{cases}$?","هل النظامان $\\begin{cases}x+y=5\\\\ 2x-y=1\\end{cases}$ و$\\begin{cases}x+y=5\\\\ 3x=6\\end{cases}$ متكافئان؟","Are $\\begin{cases}x+y=5\\\\ 2x-y=1\\end{cases}$ and $\\begin{cases}x+y=5\\\\ 3x=6\\end{cases}$ equivalent?"),solution:e("Bai: bigarrena $E_2+E_1$ da. Biek $(2,3)$ soluzioa dute.","Sí: la segunda es $E_2+E_1$. Los dos tienen la solución $(2,3)$.","نعم: الثانية هي $E_2+E_1$. ولكليهما الحل $(2,3)$.","Yes: the second is $E_2+E_1$. Both have the solution $(2,3)$.")},{id:8,difficulty:"hard",question:e("Idatzi $(3,-1)$ soluzioa duen bi ekuazioko sistema bat.","Escribe un sistema de dos ecuaciones con la solución $(3,-1)$.","اكتب نظامًا من معادلتين حله $(3,-1)$.","Write a system of two equations with the solution $(3,-1)$."),solution:e("Adibidez, $\\begin{cases}x+y=2\\\\ x-y=4\\end{cases}$.","Por ejemplo, $\\begin{cases}x+y=2\\\\ x-y=4\\end{cases}$.","مثلًا $\\begin{cases}x+y=2\\\\ x-y=4\\end{cases}$.","For example, $\\begin{cases}x+y=2\\\\ x-y=4\\end{cases}$.")},{id:9,difficulty:"hard",question:e("Zergatik ezin da ekuazio bat 0 zenbakiaz biderkatu sistema baliokideak bilatzean?","¿Por qué no se puede multiplicar una ecuación por 0 al buscar sistemas equivalentes?","لماذا لا يجوز ضرب معادلة في 0 عند البحث عن أنظمة متكافئة؟","Why can you not multiply an equation by 0 when looking for equivalent systems?"),solution:e("Ekuazioa $0x+0y=0$ bihurtzen delako eta galdu egiten delako: sistema berriak soluzio gehiago izan ditzake.","Porque la ecuación se convierte en $0x+0y=0$ y se pierde: el sistema nuevo puede tener más soluciones.","لأن المعادلة تصير $0x+0y=0$ وتضيع: قد تكون للنظام الجديد حلول أكثر.","Because the equation turns into $0x+0y=0$ and is lost: the new system may have more solutions.")},{id:10,difficulty:"hard",question:e("Aurkitu $a$ eta $b$, $\\begin{cases}ax+by=5\\\\ bx+ay=4\\end{cases}$ sistemak $(2,1)$ soluzioa izan dezan. Eman $a$.","Halla $a$ y $b$ para que $\\begin{cases}ax+by=5\\\\ bx+ay=4\\end{cases}$ tenga la solución $(2,1)$. Da $a$.","أوجد $a$ و$b$ ليكون $(2,1)$ حلًّا للنظام $\\begin{cases}ax+by=5\\\\ bx+ay=4\\end{cases}$. اكتب $a$.","Find $a$ and $b$ so that $\\begin{cases}ax+by=5\\\\ bx+ay=4\\end{cases}$ has the solution $(2,1)$. Give $a$."),solution:a("$\\begin{cases}2a+b=5\\\\ a+2b=4\\end{cases}\\ \\to\\ a=2,\\ b=1$"),answer:{expected:$(2)}}]},{id:"gauss",title:e("Gaussen metodoa","El método de Gauss","طريقة غاوس","Gaussian elimination"),items:[{id:11,difficulty:"easy",question:i("$\\begin{cases}x+y+z=4\\\\ y+z=3\\\\ z=1\\end{cases}$"),solution:a("${z}=1,\\ y=2,\\ x=1$")},{id:12,difficulty:"easy",question:s(i("$\\begin{cases}2x+y=5\\\\ 3y=3\\end{cases}$"),t("$x$")),solution:a("$y=1,\\ 2x=4,\\ x=2$"),answer:{expected:$(2)}},{id:13,difficulty:"easy",question:e("Idatzi $\\begin{cases}x+2y=3\\\\ 4x-y=1\\end{cases}$ sistemaren matrize zabaldua.","Escribe la matriz ampliada de $\\begin{cases}x+2y=3\\\\ 4x-y=1\\end{cases}$.","اكتب المصفوفة الموسعة للنظام $\\begin{cases}x+2y=3\\\\ 4x-y=1\\end{cases}$.","Write the augmented matrix of $\\begin{cases}x+2y=3\\\\ 4x-y=1\\end{cases}$."),solution:a("$\\left(\\begin{array}{cc|c}1&2&3\\\\ 4&-1&1\\end{array}\\right)$")},{id:14,difficulty:"medium",question:s(c("$\\begin{cases}x+y+z=3\\\\ x-y+z=1\\\\ x+y-z=1\\end{cases}$"),t("${z}$")),solution:a("$-2y=-2,\\ -2z=-2\\ \\to\\ y=1,\\ z=1,\\ x=1$"),answer:{expected:$(1)}},{id:15,difficulty:"medium",question:s(c("$\\begin{cases}x+2y+z=4\\\\ 2x+y+z=5\\\\ x+y+2z=3\\end{cases}$"),t("$x$")),solution:a("$-3y-z=-3,\\ -y+z=-1\\ \\to\\ -4y=-4,\\ y=1,\\ z=0,\\ x=2$"),answer:{expected:$(2)}},{id:16,difficulty:"medium",question:e("$\\left(\\begin{array}{ccc|c}1&1&1&2\\\\ 2&3&1&5\\\\ 1&0&2&1\\end{array}\\right)$ matrizean, zein eragiketak egiten dituzte zeroak lehen zutabean?","En la matriz $\\left(\\begin{array}{ccc|c}1&1&1&2\\\\ 2&3&1&5\\\\ 1&0&2&1\\end{array}\\right)$, ¿qué operaciones hacen ceros en la primera columna?","في المصفوفة $\\left(\\begin{array}{ccc|c}1&1&1&2\\\\ 2&3&1&5\\\\ 1&0&2&1\\end{array}\\right)$ أي العمليات تجعل العمود الأول أصفارًا؟","In the matrix $\\left(\\begin{array}{ccc|c}1&1&1&2\\\\ 2&3&1&5\\\\ 1&0&2&1\\end{array}\\right)$, which operations make zeros in the first column?"),solution:e("$E_2-2E_1$ eta $E_3-E_1$.","$E_2-2E_1$ y $E_3-E_1$.","$E_2-2E_1$ و$E_3-E_1$.","$E_2-2E_1$ and $E_3-E_1$.")},{id:17,difficulty:"medium",question:e("Denda batean, 3 kg sagar, 2 kg udare eta 1 kg mahats 11 € dira; kilo bana, 6 €. Mahatsa sagarra baino bi aldiz garestiagoa da. Zenbat balio du udare-kiloak?","En una tienda, 3 kg de manzanas, 2 kg de peras y 1 kg de uvas cuestan 11 €, y un kilo de cada fruta, 6 €. Las uvas cuestan el doble que las manzanas. ¿Cuánto cuesta el kilo de peras?","في متجر: 3 كغ تفاح و2 كغ إجاص و1 كغ عنب بـ 11 €، وكيلو من كل فاكهة بـ 6 €. والعنب ضعف ثمن التفاح. كم ثمن كيلو الإجاص؟","In a shop, 3 kg of apples, 2 kg of pears and 1 kg of grapes cost €11, and one kilo of each fruit costs €6. Grapes cost twice as much as apples. How much is a kilo of pears?"),solution:a("$5x+2y=11,\\ 3x+y=6\\ \\to\\ x=1,\\ y=3,\\ z=2$"),answer:{expected:$(3)}},{id:18,difficulty:"hard",question:s(c("$\\begin{cases}2x+y-z=1\\\\ x-y+z=2\\\\ x+2y+z=5\\end{cases}$"),t("$x+y+z$")),solution:e("$E_1\\leftrightarrow E_2$; gero $y-z=-1$ eta $3y=3$: $y=1$, ${z}=2$, $x=1$; $1+1+2=4$.","$E_1\\leftrightarrow E_2$; después $y-z=-1$ y $3y=3$: $y=1$, ${z}=2$, $x=1$; $1+1+2=4$.","$E_1\\leftrightarrow E_2$؛ ثم $y-z=-1$ و$3y=3$: $y=1$ و${z}=2$ و$x=1$؛ $1+1+2=4$.","$E_1\\leftrightarrow E_2$; then $y-z=-1$ and $3y=3$: $y=1$, ${z}=2$, $x=1$; $1+1+2=4$."),answer:{expected:$(4)}},{id:19,difficulty:"hard",question:e("Hiru anai-arreben adinen batura 45 urte da. Erdikoak gazteenak baino 3 urte gehiago ditu, eta zaharrenak beste bien artean dutenak ken 5. Zenbat urte ditu zaharrenak?","Tres hermanos suman 45 años. El mediano tiene 3 más que el pequeño, y el mayor tiene lo que los otros dos juntos menos 5. ¿Cuántos años tiene el mayor?","مجموع أعمار ثلاثة إخوة 45 سنة. الأوسط أكبر من الأصغر بـ 3 سنوات، وعمر الأكبر مجموع عمرَي الآخرين ناقص 5. كم عمر الأكبر؟","Three siblings' ages add up to 45. The middle one is 3 years older than the youngest, and the oldest is as old as the other two together minus 5. How old is the oldest?"),solution:a("$\\begin{cases}a+b+c=45\\\\ b=a+3\\\\ c=a+b-5\\end{cases}\\ \\to\\ 4a+1=45,\\ a=11,\\ b=14,\\ c=20$"),answer:{expected:$(20)}},{id:20,difficulty:"hard",question:e("Zergatik komeni da lehen ekuazioa $x$ ezezagunarekin eta 1 koefizientearekin hastea?","¿Por qué conviene que la primera ecuación empiece por $x$ con coeficiente 1?","لماذا يُستحسن أن تبدأ المعادلة الأولى بـ $x$ ومعامله 1؟","Why does it help if the first equation starts with $x$ with coefficient 1?"),solution:e("Horrela, besteetatik $x$ kentzeko, aski da lehena haien koefizienteaz biderkatuta kentzea, zatikirik gabe.","Porque así, para quitar la $x$ de las demás, basta restar la primera multiplicada por su coeficiente, sin fracciones.","لأنه يكفي حينئذ لحذف $x$ من البقية أن نطرح الأولى مضروبة في معاملها، دون كسور.","Because then, to remove the $x$ from the others, you just subtract the first multiplied by their coefficient, with no fractions.")}]},{id:"discussion",title:e("Sistema bat eztabaidatzea","Discutir un sistema","مناقشة نظام","Analysing a system"),items:[{id:21,difficulty:"easy",question:e("Forma mailakatuaren azken errenkada $0z=0$ da. Nolakoa da sistema?","La última fila escalonada es $0z=0$. ¿Cómo es el sistema?","الصف الأخير في الشكل الدرجي هو $0z=0$. ما نوع النظام؟","The last triangular row is $0z=0$. What kind of system is it?"),solution:e("Bateragarri indeterminatua: infinitu soluzio.","Compatible indeterminado: infinitas soluciones.","متوافق غير محدد: ما لا نهاية من الحلول.","Consistent and dependent: infinitely many solutions.")},{id:22,difficulty:"easy",question:e("Forma mailakatuaren azken errenkada $0z=7$ da. Nolakoa da sistema?","La última fila escalonada es $0z=7$. ¿Cómo es el sistema?","الصف الأخير في الشكل الدرجي هو $0z=7$. ما نوع النظام؟","The last triangular row is $0z=7$. What kind of system is it?"),solution:e("Bateraezina: ez dago $0z=7$ betetzen duen ${z}$ zenbakirik.","Incompatible: ningún ${z}$ cumple $0z=7$.","غير متوافق: لا يوجد ${z}$ يحقق $0z=7$.","Inconsistent: no ${z}$ satisfies $0z=7$.")},{id:23,difficulty:"easy",question:e("Soluzioak $(\\lambda,\\ 2\\lambda,\\ 1)$ dira. Eman $\\lambda=3$ duena.","Las soluciones son $(\\lambda,\\ 2\\lambda,\\ 1)$. Da la que tiene $\\lambda=3$.","الحلول هي $(\\lambda,\\ 2\\lambda,\\ 1)$. اكتب الحل الذي فيه $\\lambda=3$.","The solutions are $(\\lambda,\\ 2\\lambda,\\ 1)$. Give the one with $\\lambda=3$."),solution:a("$(3,6,1)$")},{id:24,difficulty:"medium",question:e("Eztabaidatu $\\begin{cases}x+y+z=1\\\\ 2x+y=3\\\\ 3x+2y+z=4\\end{cases}$.","Discute $\\begin{cases}x+y+z=1\\\\ 2x+y=3\\\\ 3x+2y+z=4\\end{cases}$.","ناقش $\\begin{cases}x+y+z=1\\\\ 2x+y=3\\\\ 3x+2y+z=4\\end{cases}$.","Analyse $\\begin{cases}x+y+z=1\\\\ 2x+y=3\\\\ 3x+2y+z=4\\end{cases}$."),solution:e("$E_2-2E_1$ eta $E_3-3E_1$ eragiketek $-y-2z=1$ ematen dute biek: bateragarri indeterminatua.","$E_2-2E_1$ y $E_3-3E_1$ dan las dos $-y-2z=1$: compatible indeterminado.","تعطي $E_2-2E_1$ و$E_3-3E_1$ كلتاهما $-y-2z=1$: متوافق غير محدد.","$E_2-2E_1$ and $E_3-3E_1$ both give $-y-2z=1$: consistent and dependent.")},{id:25,difficulty:"medium",question:e("Ebatzi $\\begin{cases}x-y=1\\\\ y-z=2\\end{cases}$, ${z}=\\lambda$ eginda. Eman $x$, $\\lambda=0$ denean.","Resuelve $\\begin{cases}x-y=1\\\\ y-z=2\\end{cases}$ con ${z}=\\lambda$. Da $x$ para $\\lambda=0$.","حُلّ $\\begin{cases}x-y=1\\\\ y-z=2\\end{cases}$ مع ${z}=\\lambda$. اكتب $x$ عندما $\\lambda=0$.","Solve $\\begin{cases}x-y=1\\\\ y-z=2\\end{cases}$ with ${z}=\\lambda$. Give $x$ for $\\lambda=0$."),solution:a("$(3+\\lambda,\\ 2+\\lambda,\\ \\lambda)\\ \\to\\ (3,2,0)$"),answer:{expected:$(3)}},{id:26,difficulty:"medium",question:e("Aurkitu $a$, $\\begin{cases}x+y=1\\\\ ax+2y=2\\end{cases}$ sistemak soluzio bakarra izan ez dezan.","Halla $a$ para que $\\begin{cases}x+y=1\\\\ ax+2y=2\\end{cases}$ no tenga una sola solución.","أوجد $a$ لكي لا يكون للنظام $\\begin{cases}x+y=1\\\\ ax+2y=2\\end{cases}$ حل واحد فقط.","Find $a$ so that $\\begin{cases}x+y=1\\\\ ax+2y=2\\end{cases}$ does not have exactly one solution."),solution:e("$a=2$ denean, bigarrena lehenaren bikoitza da: infinitu soluzio.","Con $a=2$, la segunda es el doble de la primera: infinitas soluciones.","مع $a=2$ تكون الثانية ضعف الأولى: ما لا نهاية من الحلول.","With $a=2$, the second is twice the first: infinitely many solutions."),answer:{expected:$(2)}},{id:27,difficulty:"medium",question:e("Eztabaidatu $\\begin{cases}x+y=3\\\\ 2x+2y=a\\end{cases}$, $a$ zenbakiaren arabera.","Discute $\\begin{cases}x+y=3\\\\ 2x+2y=a\\end{cases}$ según $a$.","ناقش $\\begin{cases}x+y=3\\\\ 2x+2y=a\\end{cases}$ حسب $a$.","Analyse $\\begin{cases}x+y=3\\\\ 2x+2y=a\\end{cases}$ for the values of $a$."),solution:e("$a=6$ bada, bateragarri indeterminatua; $a\\neq 6$ bada, bateraezina.","Si $a=6$, compatible indeterminado; si $a\\neq 6$, incompatible.","إذا كان $a=6$ فهو متوافق غير محدد؛ وإذا كان $a\\neq 6$ فهو غير متوافق.","If $a=6$, consistent and dependent; if $a\\neq 6$, inconsistent.")},{id:28,difficulty:"hard",question:e("Eztabaidatu $\\begin{cases}x+y+z=1\\\\ x+2y+z=2\\\\ x+y+az=3\\end{cases}$, $a$ zenbakiaren arabera.","Discute $\\begin{cases}x+y+z=1\\\\ x+2y+z=2\\\\ x+y+az=3\\end{cases}$ según $a$.","ناقش $\\begin{cases}x+y+z=1\\\\ x+2y+z=2\\\\ x+y+az=3\\end{cases}$ حسب $a$.","Analyse $\\begin{cases}x+y+z=1\\\\ x+2y+z=2\\\\ x+y+az=3\\end{cases}$ for the values of $a$."),solution:e("$E_3-E_1$ eragiketak $(a-1)z=2$ ematen du: $a=1$ bada, bateraezina; $a\\neq 1$ bada, bateragarri determinatua.","$E_3-E_1$ da $(a-1)z=2$: si $a=1$, incompatible; si $a\\neq 1$, compatible determinado.","تعطي $E_3-E_1$ المعادلة $(a-1)z=2$: إذا كان $a=1$ فهو غير متوافق؛ وإذا كان $a\\neq 1$ فهو متوافق محدد.","$E_3-E_1$ gives $(a-1)z=2$: if $a=1$, inconsistent; if $a\\neq 1$, consistent and independent.")},{id:29,difficulty:"hard",question:e("Idatzi $(\\lambda,\\ 1,\\ 2-\\lambda)$ soluzioak dituen hiru ekuazioko sistema bat.","Escribe un sistema de tres ecuaciones con las soluciones $(\\lambda,\\ 1,\\ 2-\\lambda)$.","اكتب نظامًا من ثلاث معادلات حلوله $(\\lambda,\\ 1,\\ 2-\\lambda)$.","Write a system of three equations whose solutions are $(\\lambda,\\ 1,\\ 2-\\lambda)$."),solution:e("Adibidez, $\\begin{cases}x+z=2\\\\ y=1\\\\ 2x+y+2z=5\\end{cases}$; hirugarrena $2E_1+E_2$ da.","Por ejemplo, $\\begin{cases}x+z=2\\\\ y=1\\\\ 2x+y+2z=5\\end{cases}$; la tercera es $2E_1+E_2$.","مثلًا $\\begin{cases}x+z=2\\\\ y=1\\\\ 2x+y+2z=5\\end{cases}$؛ والثالثة هي $2E_1+E_2$.","For example, $\\begin{cases}x+z=2\\\\ y=1\\\\ 2x+y+2z=5\\end{cases}$; the third is $2E_1+E_2$.")},{id:30,difficulty:"hard",question:e("Aurkitu $a$ eta $b$, $\\begin{cases}x+2y=3\\\\ 2x+ay=b\\end{cases}$ sistemak infinitu soluzio izan ditzan. Eman $a+b$.","Halla $a$ y $b$ para que $\\begin{cases}x+2y=3\\\\ 2x+ay=b\\end{cases}$ tenga infinitas soluciones. Da $a+b$.","أوجد $a$ و$b$ ليكون للنظام $\\begin{cases}x+2y=3\\\\ 2x+ay=b\\end{cases}$ ما لا نهاية من الحلول. اكتب $a+b$.","Find $a$ and $b$ so that $\\begin{cases}x+2y=3\\\\ 2x+ay=b\\end{cases}$ has infinitely many solutions. Give $a+b$."),solution:a("$E_2-2E_1\\ \\to\\ (a-4)y=b-6\\qquad a=4,\\ b=6,\\ a+b=10$"),answer:{expected:$(10)}}]},{id:"nonlinear",title:e("Sistema ez-linealak","Sistemas no lineales","الأنظمة غير الخطية","Non-linear systems"),items:[{id:31,difficulty:"easy",question:i("$\\begin{cases}y=x^2\\\\ y=4\\end{cases}$"),solution:e("$x^2=4$: $(2,4)$ eta $(-2,4)$.","$x^2=4$: $(2,4)$ y $(-2,4)$.","$x^2=4$: $(2,4)$ و$(-2,4)$.","$x^2=4$: $(2,4)$ and $(-2,4)$.")},{id:32,difficulty:"easy",question:s(i("$\\begin{cases}x+y=7\\\\ xy=10\\end{cases}$"),r),solution:a("$x^2-7x+10=0\\ \\to\\ x=2,\\ x=5$"),answer:{expected:$(5)}},{id:33,difficulty:"easy",question:s(i("$\\begin{cases}2^x=16\\\\ 3^y=9\\end{cases}$"),t("$x+y$")),solution:a("$x=4,\\ y=2\\qquad 4+2=6$"),answer:{expected:$(6)}},{id:34,difficulty:"medium",question:e("Ebatzi $\\begin{cases}x^2+y^2=25\\\\ x-y=1\\end{cases}$. $x$ positiboa duen soluzioan, zenbat balio du $y$ ezezagunak?","Resuelve $\\begin{cases}x^2+y^2=25\\\\ x-y=1\\end{cases}$. En la solución con $x$ positiva, ¿cuánto vale $y$?","حُلّ $\\begin{cases}x^2+y^2=25\\\\ x-y=1\\end{cases}$. في الحل الذي فيه $x$ موجب، كم قيمة $y$؟","Solve $\\begin{cases}x^2+y^2=25\\\\ x-y=1\\end{cases}$. In the solution with positive $x$, what is $y$?"),solution:a("$y^2+y-12=0\\ \\to\\ y=3,\\ y=-4\\qquad (4,3),\\ (-3,-4)$"),answer:{expected:$(3)}},{id:35,difficulty:"medium",question:s(e("Begiratu $\\begin{cases}x^2+y^2=13\\\\ x^2-y^2=5\\end{cases}$ sistemari.","Mira el sistema $\\begin{cases}x^2+y^2=13\\\\ x^2-y^2=5\\end{cases}$.","انظر إلى النظام $\\begin{cases}x^2+y^2=13\\\\ x^2-y^2=5\\end{cases}$.","Look at the system $\\begin{cases}x^2+y^2=13\\\\ x^2-y^2=5\\end{cases}$."),y),solution:e("$x^2=9$ eta $y^2=4$: $x=\\pm 3$, $y=\\pm 2$, lau bikote.","$x^2=9$ e $y^2=4$: $x=\\pm 3$, $y=\\pm 2$, cuatro pares.","$x^2=9$ و$y^2=4$: $x=\\pm 3$ و$y=\\pm 2$، أي أربعة أزواج.","$x^2=9$ and $y^2=4$: $x=\\pm 3$, $y=\\pm 2$, four pairs."),answer:{expected:$(4)}},{id:36,difficulty:"medium",question:s(i("$\\begin{cases}\\log x-\\log y=1\\\\ x+y=22\\end{cases}$"),t("$x$")),solution:a("$\\frac{x}{y}=10\\ \\to\\ 11y=22,\\ y=2,\\ x=20$"),answer:{expected:$(20)}},{id:37,difficulty:"medium",question:s(i("$\\begin{cases}2^{x+y}=8\\\\ 2^{x-y}=2\\end{cases}$"),t("$x$")),solution:a("$x+y=3,\\ x-y=1\\ \\to\\ x=2$"),answer:{expected:$(2)}},{id:38,difficulty:"hard",question:s(e("Begiratu $\\begin{cases}y=x^3\\\\ y=4x\\end{cases}$ sistemari.","Mira el sistema $\\begin{cases}y=x^3\\\\ y=4x\\end{cases}$.","انظر إلى النظام $\\begin{cases}y=x^3\\\\ y=4x\\end{cases}$.","Look at the system $\\begin{cases}y=x^3\\\\ y=4x\\end{cases}$."),y),solution:e("$x(x-2)(x+2)=0$, eta 3 soluzio: $(0,0)$, $(2,8)$ eta $(-2,-8)$.","$x(x-2)(x+2)=0$, con 3 soluciones: $(0,0)$, $(2,8)$ y $(-2,-8)$.","$x(x-2)(x+2)=0$، أي 3 حلول: $(0,0)$ و$(2,8)$ و$(-2,-8)$.","$x(x-2)(x+2)=0$, with 3 solutions: $(0,0)$, $(2,8)$ and $(-2,-8)$."),answer:{expected:$(3)}},{id:39,difficulty:"hard",question:e("Laukizuzen baten diagonalak 17 cm ditu, eta perimetroak 46 cm. Zenbat neurtzen du alde handienak, zentimetrotan?","Un rectángulo tiene 17 cm de diagonal y 46 cm de perímetro. ¿Cuánto mide el lado mayor, en centímetros?","مستطيل قطره 17 سم ومحيطه 46 سم. كم طول الضلع الأكبر بالسنتيمتر؟","A rectangle has a diagonal of 17 cm and a perimeter of 46 cm. How long is the longer side, in centimetres?"),solution:e("$x+y=23$ eta $x^2+y^2=289$, beraz $xy=120$: aldeek 8 eta 15 neurtzen dute.","$x+y=23$ y $x^2+y^2=289$, así que $xy=120$: los lados miden 8 y 15.","$x+y=23$ و$x^2+y^2=289$، إذن $xy=120$: طولا الضلعين 8 و15.","$x+y=23$ and $x^2+y^2=289$, so $xy=120$: the sides are 8 and 15."),answer:{expected:$(15)}},{id:40,difficulty:"hard",question:e("Azaldu zergatik ez duen soluziorik $\\begin{cases}x^2+y^2=4\\\\ x+y=5\\end{cases}$ sistemak.","Explica por qué $\\begin{cases}x^2+y^2=4\\\\ x+y=5\\end{cases}$ no tiene solución.","اشرح لماذا ليس للنظام $\\begin{cases}x^2+y^2=4\\\\ x+y=5\\end{cases}$ حل.","Explain why $\\begin{cases}x^2+y^2=4\\\\ x+y=5\\end{cases}$ has no solution."),solution:e("$2x^2-10x+21=0$ ateratzen da, $\\Delta=100-168<0$ duena: zuzenak ez du zirkunferentzia ebakitzen.","Sale $2x^2-10x+21=0$, con $\\Delta=100-168<0$: la recta no corta a la circunferencia.","نحصل على $2x^2-10x+21=0$ ومميزها $\\Delta=100-168<0$: المستقيم لا يقطع الدائرة.","You get $2x^2-10x+21=0$, with $\\Delta=100-168<0$: the line does not meet the circle.")}]},{id:"inequalities",title:e("Bi ezezaguneko inekuazioak","Inecuaciones con dos incógnitas","متراجحات بمجهولين","Inequalities in two unknowns"),items:[{id:41,difficulty:"easy",question:e("$(1,2)$ puntuak betetzen al du $x+y\\le 4$ inekuazioa?","¿Cumple $(1,2)$ la inecuación $x+y\\le 4$?","هل تحقق $(1,2)$ المتراجحة $x+y\\le 4$؟","Does $(1,2)$ satisfy the inequality $x+y\\le 4$?"),solution:e("Bai: $1+2=3$, eta $3\\le 4$.","Sí: $1+2=3$ y $3\\le 4$.","نعم: $1+2=3$ و$3\\le 4$.","Yes: $1+2=3$ and $3\\le 4$.")},{id:42,difficulty:"easy",question:e("Zein proba-puntu erabiliko zenuke $2x-y>3$ inekuazioan?","¿Qué punto de prueba usarías para $2x-y>3$?","أي نقطة اختبار تستعمل للمتراجحة $2x-y>3$؟","Which test point would you use for $2x-y>3$?"),solution:e("$(0,0)$ puntua, zuzenean ez dagoena: $0>3$ faltsua da; beraz, soluzioa $O$ ez dagoen aldea da.","El $(0,0)$, que no está en la recta: $0>3$ es falso, así que la solución es el lado sin $O$.","النقطة $(0,0)$ لأنها ليست على المستقيم: $0>3$ خطأ، إذن الحل هو الجانب الذي ليس فيه $O$.","$(0,0)$, which is not on the line: $0>3$ is false, so the solution is the side without $O$.")},{id:43,difficulty:"easy",question:i("$y\\ge 2$"),solution:e("$y=2$ zuzenaren gaineko erdiplanoa, zuzena barne.","El semiplano por encima de la recta $y=2$, con la recta incluida.","نصف المستوى فوق المستقيم $y=2$، والمستقيم داخل فيه.","The half-plane above the line $y=2$, with the line included.")},{id:44,difficulty:"medium",question:l("$\\begin{cases}x\\ge 1\\\\ y\\ge 1\\\\ x+y\\le 4\\end{cases}$"),solution:e("$x=1$ denean, 3; $x=2$ denean, 2; $x=3$ denean, 1. Guztira, $3+2+1=6$.","Con $x=1$ hay 3; con $x=2$, 2; con $x=3$, 1. En total, $3+2+1=6$.","مع $x=1$ ثلاث، ومع $x=2$ اثنتان، ومع $x=3$ واحدة. المجموع $3+2+1=6$.","With $x=1$ there are 3; with $x=2$, 2; with $x=3$, 1. In all, $3+2+1=6$."),answer:{expected:$(6)}},{id:45,difficulty:"medium",question:e("Aurkitu $\\begin{cases}x\\ge 0\\\\ y\\ge 0\\\\ x+2y\\le 6\\end{cases}$ eskualdearen erpinak.","Halla los vértices de la región $\\begin{cases}x\\ge 0\\\\ y\\ge 0\\\\ x+2y\\le 6\\end{cases}$.","أوجد رؤوس المنطقة $\\begin{cases}x\\ge 0\\\\ y\\ge 0\\\\ x+2y\\le 6\\end{cases}$.","Find the vertices of the region $\\begin{cases}x\\ge 0\\\\ y\\ge 0\\\\ x+2y\\le 6\\end{cases}$."),solution:a("$(0,0),\\ (6,0),\\ (0,3)$")},{id:46,difficulty:"medium",question:e("Hutsa al da $\\begin{cases}x+y\\le 2\\\\ x\\ge 3\\\\ y\\ge 0\\end{cases}$ eskualdea?","¿Es vacía la región $\\begin{cases}x+y\\le 2\\\\ x\\ge 3\\\\ y\\ge 0\\end{cases}$?","هل المنطقة $\\begin{cases}x+y\\le 2\\\\ x\\ge 3\\\\ y\\ge 0\\end{cases}$ خالية؟","Is the region $\\begin{cases}x+y\\le 2\\\\ x\\ge 3\\\\ y\\ge 0\\end{cases}$ empty?"),solution:e("Bai: $x\\ge 3$ eta $y\\ge 0$ badira, $x+y\\ge 3$, eta hori 2 baino handiagoa da.","Sí: con $x\\ge 3$ e $y\\ge 0$, $x+y\\ge 3$, que es más que 2.","نعم: مع $x\\ge 3$ و$y\\ge 0$ يكون $x+y\\ge 3$، وهو أكبر من 2.","Yes: with $x\\ge 3$ and $y\\ge 0$, $x+y\\ge 3$, which is more than 2.")},{id:47,difficulty:"medium",question:e("Irekia ala itxia da $\\begin{cases}y\\ge 0\\\\ y\\le x\\end{cases}$ eskualdea?","¿Es abierta o cerrada la región $\\begin{cases}y\\ge 0\\\\ y\\le x\\end{cases}$?","هل المنطقة $\\begin{cases}y\\ge 0\\\\ y\\le x\\end{cases}$ مفتوحة أم مغلقة؟","Is the region $\\begin{cases}y\\ge 0\\\\ y\\le x\\end{cases}$ open or closed?"),solution:e("Irekia: eskuinera jarraitzen du, amaierarik gabe.","Abierta: sigue sin fin hacia la derecha.","مفتوحة: تمتد بلا نهاية نحو اليمين.","Open: it goes on without end to the right.")},{id:48,difficulty:"hard",question:e("Zinema batean sarrerak 6 eta 8 euroan daude, eta talde batek gehienez 48 € gastatu nahi ditu. 6 euroko gutxienez 2 sarrera erosten badituzte, zenbat sarrera eros ditzakete gehienez 8 euroan?","Un cine tiene entradas de 6 € y de 8 €, y un grupo quiere gastar como mucho 48 €. Si compran al menos 2 de 6 €, ¿cuántas de 8 € pueden comprar como máximo?","في سينما تذاكر بـ 6 € و8 €، وتريد مجموعة أن تنفق 48 € على الأكثر. إذا اشتروا تذكرتين على الأقل بـ 6 € فكم تذكرة بـ 8 € يمكنهم شراؤها على الأكثر؟","A cinema sells €6 and €8 tickets, and a group wants to spend at most €48. If they buy at least 2 tickets at €6, how many €8 tickets can they buy at most?"),solution:e("$6\\cdot 2+8y\\le 48$, beraz $y\\le 4{,}5$: gehienez 4.","$6\\cdot 2+8y\\le 48$, así que $y\\le 4{,}5$: como mucho 4.","$6\\cdot 2+8y\\le 48$، إذن $y\\le 4{,}5$: على الأكثر 4.","$6\\cdot 2+8y\\le 48$, so $y\\le 4{,}5$: at most 4."),answer:{expected:$(4)}},{id:49,difficulty:"hard",question:e("Aurkitu $\\begin{cases}x\\ge 0\\\\ y\\ge 0\\\\ x\\le 4\\\\ y\\le 3\\end{cases}$ eskualdearen azalera.","Halla el área de la región $\\begin{cases}x\\ge 0\\\\ y\\ge 0\\\\ x\\le 4\\\\ y\\le 3\\end{cases}$.","أوجد مساحة المنطقة $\\begin{cases}x\\ge 0\\\\ y\\ge 0\\\\ x\\le 4\\\\ y\\le 3\\end{cases}$.","Find the area of the region $\\begin{cases}x\\ge 0\\\\ y\\ge 0\\\\ x\\le 4\\\\ y\\le 3\\end{cases}$."),solution:e("Laukizuzen bat da: $4\\cdot 3=12$.","Es un rectángulo de $4\\cdot 3=12$.","إنها مستطيل مساحته $4\\cdot 3=12$.","It is a rectangle: $4\\cdot 3=12$."),answer:{expected:$(12)}},{id:50,difficulty:"hard",question:e("Idatzi eskualdea $(0,0)$, $(4,0)$ eta $(0,4)$ erpinak dituen triangelua duen inekuazio-sistema bat.","Escribe un sistema de inecuaciones cuya región sea el triángulo de vértices $(0,0)$, $(4,0)$ y $(0,4)$.","اكتب نظام متراجحات منطقته المثلث ذو الرؤوس $(0,0)$ و$(4,0)$ و$(0,4)$.","Write a system of inequalities whose region is the triangle with vertices $(0,0)$, $(4,0)$ and $(0,4)$."),solution:a("$\\begin{cases}x\\ge 0\\\\ y\\ge 0\\\\ x+y\\le 4\\end{cases}$")}]}];export{p as a,z as b,m as c,g as d};
